    "id": "log-805-glossaire-reconstitue",
    "kind": "glossaire",
    "blocks": [
      {
        "kind": "paragraph",
        "text": "{g}alignement{/g} — Position du texte par rapport aux bords de la zone de saisie."
      },
      {
        "kind": "paragraph",
        "text": "{g}bibliographie{/g} — Liste des références utilisées pour préparer le document."
      },
      {
        "kind": "paragraph",
        "text": "{g}cellule{/g} — Intersection d’une ligne et d’une colonne dans un tableau."
      },
      {
        "kind": "paragraph",
        "text": "{g}citation{/g} — Renvoi à une source dans le corps d’un document."
      },
      {
        "kind": "paragraph",
        "text": "{g}en-tête{/g} — Zone située en haut de la page, souvent répétée selon les réglages."
      },
      {
        "kind": "paragraph",
        "text": "{g}fusion de cellules{/g} — Réunion de plusieurs cellules contiguës en une seule."
      },
      {
        "kind": "paragraph",
        "text": "{g}habillage{/g} — Réglage qui organise la circulation du texte autour d’un objet."
      },
      {
        "kind": "paragraph",
        "text": "{g}interligne{/g} — Espacement entre les lignes d’un paragraphe."
      },
      {
        "kind": "paragraph",
        "text": "{g}légende{/g} — Texte associé à une figure ou à un tableau pour l’identifier."
      },
      {
        "kind": "paragraph",
        "text": "{g}marge{/g} — Distance entre le bord de page et la zone disponible pour le document."
      },
      {
        "kind": "paragraph",
        "text": "{g}note de bas de page{/g} — Information complémentaire généralement placée au bas de la page de son appel."
      },
      {
        "kind": "paragraph",
        "text": "{g}note de fin{/g} — Information complémentaire rassemblée en fin de document ou de section."
      },
      {
        "kind": "paragraph",
        "text": "{g}paragraphe{/g} — Unité de texte pouvant partager une mise en forme de paragraphe."
      },
      {
        "kind": "paragraph",
        "text": "{g}pied de page{/g} — Zone située en bas de la page qui peut contenir un numéro ou une référence."
      },
      {
        "kind": "paragraph",
        "text": "{g}retrait{/g} — Décalage d’un paragraphe par rapport aux limites de la zone de texte."
      },
      {
        "kind": "paragraph",
        "text": "{g}rognage{/g} — Masquage d’une partie des bords d’une image pour modifier le cadrage."
      },
      {
        "kind": "paragraph",
        "text": "{g}saut de ligne{/g} — Passage à la ligne à l’intérieur du même paragraphe."
      },
      {
        "kind": "paragraph",
        "text": "{g}saut de page{/g} — Commande qui déplace la suite du document au début de la page suivante."
      },
      {
        "kind": "paragraph",
        "text": "{g}section{/g} — Partie d’un document pouvant avoir ses propres réglages de mise en page."
      },
      {
        "kind": "paragraph",
        "text": "{g}style{/g} — Ensemble nommé de réglages de présentation réutilisables."
      },
      {
        "kind": "paragraph",
        "text": "{g}table des illustrations{/g} — Liste des figures ou autres objets légendés accompagnés de leur page."
      },
      {
        "kind": "paragraph",
        "text": "{g}table des matières{/g} — Liste structurée des titres du document et de leur emplacement."
      },
      {
        "kind": "paragraph",
        "text": "{g}trame de fond{/g} — Couleur ou motif de remplissage derrière un texte ou dans une cellule."
      }
    ],
